"""Loads the shared Escape from Tarkov data table generated by tools/extract_data.py.

The same JSON file ships inside the SPT server mod, so item and location IDs always
match between the APWorld and the game side.
"""
import json
import pkgutil
from functools import lru_cache
from typing import Any, Dict


@lru_cache(maxsize=1)
def load_data() -> Dict[str, Any]:
    raw = pkgutil.get_data(__name__, "tarkov_data.json")
    if raw is None:
        raise FileNotFoundError("tarkov_data.json is missing from the Escape from Tarkov APWorld")
    return json.loads(raw.decode("utf-8"))
